class Solution {
    public int maxPower(String text){
        int current=1,answer=1;
        for(int i=1;i<text.length();i++){
            current=text.charAt(i)==text.charAt(i-1)?current+1:1;
            answer=Math.max(answer,current);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxPower(text:String):Int{
        var current=1;
        var answer=1;
        for(i in 1 until text.length){
            current=if(text[i]==text[i-1])current+1 else 1;
            answer=maxOf(answer,current)
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int maxPower(string text){
        int current=1,answer=1;
        for(int i=1;i<(int)text.size();++i){
            current=text[i]==text[i-1]?current+1:1;
            answer=max(answer,current);
        }
        return answer;
    }
};
